    return () => cardPopupService.removeEventListener(eventType, listener)
}

import type { ActionDefinition, RawActionDefinition } from '../data/action_types'
import type { Card } from '../data/data_types'
import type { AgentInstructionFile } from './agent_instructions/agent_instruction_file'

export type OpenDocumentObject = ActionDefinition | AgentInstructionFile | Card
export interface CardBodyDraft {
    content: string
}
export type OpenDocumentDraft = CardBodyDraft | RawActionDefinition
export type OpenDocumentOrigin = object | string | null

export interface OpenDocumentSaveReference {
    readonly document: OpenDocument
    acknowledge(): void
}

export interface OpenDocumentChangedDetail {
    document: OpenDocument
    origin: OpenDocumentOrigin
    type: 'dirty' | 'draft' | 'renewed' | 'saved'
}

interface OpenDocumentBase<TObject extends OpenDocumentObject, TDraft extends OpenDocumentDraft> extends EventTarget {
    readonly dirty: boolean
    readonly kind: 'action' | 'card' | 'instruction'
    readonly path: string
    createSaveReference(): OpenDocumentSaveReference
    getDraft(): TDraft
    getObject(): TObject
    replaceDraft(draft: TDraft): void
    updateDraft(draft: TDraft, origin?: OpenDocumentOrigin): void
}

export interface ActionOpenDocument extends OpenDocumentBase<ActionDefinition, RawActionDefinition> {
    readonly kind: 'action'
}

export interface CardOpenDocument extends OpenDocumentBase<Card, CardBodyDraft> {
    readonly kind: 'card'
}

export interface InstructionOpenDocument extends OpenDocumentBase<AgentInstructionFile, CardBodyDraft> {
    readonly kind: 'instruction'
}

export type OpenDocument = ActionOpenDocument | CardOpenDocument | InstructionOpenDocument

import type {
    CardBodyDraft,
    OpenDocument,
    OpenDocumentChangedDetail,
    OpenDocumentDraft,
    OpenDocumentObject,
    OpenDocumentOrigin,
    OpenDocumentSaveReference,
} from './open_document'

function isCardDraft(draft: OpenDocumentDraft): draft is CardBodyDraft {
    return 'content' in draft
}

function isCardObject(object: OpenDocumentObject) {
    return 'header' in object
}

function isActionObject(object: OpenDocumentObject) {
    return 'id' in object
}

function objectPath(kind: ManagedOpenDocument['kind'], object: OpenDocumentObject) {
    if (isCardObject(object)) return object.path
    if (!isActionObject(object)) return object.path
    if (kind === 'instruction') throw new Error('Instruction document requires an instruction object')
    if (!object.sourcePath) throw new Error(`Action document requires a source path: ${object.id}`)

    return object.sourcePath
}

/** Stable document identity with revision-based draft persistence state. */
export class ManagedOpenDocument extends EventTarget {
    readonly identity: string
    readonly kind: 'action' | 'card' | 'instruction'
    private acknowledgedRevision = 0
    private draft: OpenDocumentDraft
    private editRevision = 0
    private object: OpenDocumentObject

    constructor(
        kind: 'action' | 'card' | 'instruction',
        identity: string,
        object: OpenDocumentObject,
        draft: OpenDocumentDraft,
    ) {
        super()
        this.kind = kind
        this.identity = identity
        this.object = object
        this.draft = draft
    }

    get dirty() { return this.editRevision !== this.acknowledgedRevision }
    get path() { return objectPath(this.kind, this.object) }

    getDraft() {
        return this.draft
    }

    getObject() {
        return this.object
    }

    updateDraft(draft: OpenDocumentDraft, origin: OpenDocumentOrigin = null) {
        if (this.draft === draft) return

        const wasDirty = this.dirty
        this.applyDraft(draft)
        this.editRevision += 1
        this.dispatchChanged('draft', origin)
        if (!wasDirty) this.dispatchChanged('dirty', origin)
    }

    replaceDraft(draft: OpenDocumentDraft) {
        const wasDirty = this.dirty
        this.applyDraft(draft)
        this.editRevision += 1
        this.acknowledgedRevision = this.editRevision
        this.dispatchChanged('draft', null)
        if (wasDirty) this.dispatchChanged('dirty', null)
    }

    createSaveReference(): OpenDocumentSaveReference {
        const revision = this.editRevision

        return { document: this as unknown as OpenDocument, acknowledge: () => this.acknowledge(revision) }
    }

    renew(identity: string, object: OpenDocumentObject, draft: OpenDocumentDraft) {
        if (this.identity !== identity) throw new Error(`Cannot renew open ${this.kind} document with a different object`)
        const sameDraft = this.kind !== 'action'
            ? isCardDraft(this.draft) && isCardDraft(draft) && this.draft.content === draft.content
            : this.draft === draft
        if (this.object === object && sameDraft) return

        const previousObject = this.object
        const draftChanged = !this.dirty && !sameDraft
        this.object = object
        if (draftChanged) this.draft = draft
        const detail = { document: this, object, origin: null, previousObject, type: 'renewed' }
        this.dispatchEvent(new CustomEvent('changed', { detail }))
        if (draftChanged) this.dispatchChanged('draft', null)
    }

    private acknowledge(revision: number) {
        if (revision <= this.acknowledgedRevision) return

        const wasDirty = this.dirty
        this.acknowledgedRevision = revision
        this.dispatchChanged('saved', null)
        if (wasDirty && !this.dirty) this.dispatchChanged('dirty', null)
    }

    private applyDraft(draft: OpenDocumentDraft) {
        if (this.kind !== 'action') {
            if (!('content' in draft)) throw new Error(`Cannot update ${this.kind} document with a different draft kind`)
            if (this.kind === 'card' && !isCardObject(this.object)) throw new Error('Cannot update card document with a different object kind')
            this.draft = draft
            return
        }

        this.draft = draft
    }

    private dispatchChanged(type: OpenDocumentChangedDetail['type'], origin: OpenDocumentOrigin) {
        const detail: OpenDocumentChangedDetail = { document: this as unknown as OpenDocument, origin, type }
        this.dispatchEvent(new CustomEvent<OpenDocumentChangedDetail>('changed', { detail }))
    }
}

