import { Box } from '@mui/material'
import { memo, useCallback, useEffect, useState } from 'react'
import { openFilesService, type OpenDocumentEventDetail } from '../../../services/open_files_service'
import { actionMarkdownDataSource } from '../../editor/data_sources/action_markdown_data_source'
import { sameMarkdownTarget, type MarkdownDocumentTarget } from '../../editor/data_sources/markdown_data_source'
import { MarkdownDocumentHistoryStore } from '../../editor/history/markdown_document_history_store'
import { MarkdownEditor } from '../../editor/markdown_editor'
import { ActionEditor, type ActionMarkdownPresentation } from './action_editor'
import { useOpenFiles } from '../../hooks/use_open_files'
import { actionService } from '../../../services/actions/action_service'
import { useRetainedActionDocument } from './use_retained_action_document'
import { useProjectReadOnly } from '../../hooks/use_project_read_only'

interface ListActionEditorProps {
    cardTypes: string[]
    specialContextTypes: string[]
    states: string[]
}

/** Lifetime-stable list action editor surface and binding-owned undo store. */
export const ListActionEditor = memo(function ListActionEditor(props: ListActionEditorProps) {
    const { cardTypes, specialContextTypes, states } = props
    const readOnly = useProjectReadOnly()
    const { activeDocument } = useOpenFiles()
    const activeActionDocument = activeDocument?.kind === 'action' ? activeDocument : null
    const retainedActionDocument = useRetainedActionDocument()
    const retainedAction = retainedActionDocument?.getObject() ?? null
    const retainedPath = retainedAction?.sourcePath
    const actionExists = !!retainedPath && (
        !!actionService.getEditableActionByPath(retainedPath)
        || actionService.draftStore.getDeletedDraftActions().some((candidate) => candidate.sourcePath === retainedPath)
    )
    const action = actionExists ? retainedAction : null
    const [historyStore] = useState(() => new MarkdownDocumentHistoryStore())
    const [presentation, setPresentation] = useState<ActionMarkdownPresentation | null>(null)

    const discardMarkdownTarget = useCallback((target: MarkdownDocumentTarget) => {
        historyStore.discardTarget(target)
        const activeTarget = actionMarkdownDataSource.getActiveTarget('list-action')
        if (sameMarkdownTarget(activeTarget, target)) actionMarkdownDataSource.setActiveActionTarget(null, true)
    }, [historyStore])

    useEffect(() => {
        const handleRemoved = (event: Event) => {
            const { document } = (event as CustomEvent<OpenDocumentEventDetail>).detail
            if (document.kind !== 'action') return

            historyStore.discardDocument(document)
            const activeTarget = actionMarkdownDataSource.getActiveTarget('list-action')
            if (activeTarget?.document === document) {
                actionMarkdownDataSource.setActiveActionTarget(null)
                setPresentation(null)
            }
        }
        openFilesService.addEventListener('removed', handleRemoved)

        return () => openFilesService.removeEventListener('removed', handleRemoved)
    }, [historyStore])

    useEffect(() => () => actionMarkdownDataSource.setActiveActionTarget(null), [])

    return (
        <Box
            data-testid="list-action-editor"
            hidden={!activeActionDocument}
            sx={{ display: activeActionDocument ? 'contents' : 'none' }}
        >
            {action && retainedActionDocument ? (
                <ActionEditor
                    actionDocument={retainedActionDocument}
                    cardTypes={cardTypes}
                    discardMarkdownTarget={discardMarkdownTarget}
                    onMarkdownPresentationChange={setPresentation}
                    specialContextTypes={specialContextTypes}
                    states={states}
                />
            ) : null}
            <Box hidden={!presentation} sx={{ flex: 1, minHeight: 0, order: 1, overflowY: 'auto' }}>
                <MarkdownEditor
                    binding="list-action"
                    dataSource={actionMarkdownDataSource}
                    flushOnBlur
                    historyStore={historyStore}
                    placeholders={presentation?.placeholders}
                    readOnly={readOnly}
                    toolbarContents={readOnly ? undefined : presentation?.toolbarContents}
                />
            </Box>
        </Box>
    )
})

import { CARD_PATH_CHANGED_EVENT, dataService, type CardPathChangedEventDetail, type DataService } from '../data/data_service'
import { register } from '../service_injector'

export type WorkspaceViewMode = 'cards' | 'diagrams' | 'stats' | 'text'

export interface WorkspaceViewSnapshot {
    selectedPath: string | null
    viewMode: WorkspaceViewMode
}

const INITIAL_SNAPSHOT: WorkspaceViewSnapshot = { selectedPath: null, viewMode: 'cards' }

/** Shared UI state for the project workspace view mode and selected card/file path. */
export class WorkspaceViewService extends EventTarget {
    private projectKey: string | null = null
    private snapshot = INITIAL_SNAPSHOT
    private readonly dataService: DataService

    constructor(dataServiceInstance: DataService) {
        super()
        this.dataService = dataServiceInstance
        this.projectKey = this.currentProjectKey()
        this.dataService.addEventListener('changed', this.handleDataServiceChanged)
        this.dataService.addEventListener(CARD_PATH_CHANGED_EVENT, this.handleCardPathChanged)
    }

    getSnapshot(): WorkspaceViewSnapshot {
        return this.snapshot
    }

    selectPath(path: string) {
        if (!path) throw new Error('Cannot select a workspace path without a path')

        this.update({ ...this.snapshot, selectedPath: path })
    }

    clearSelectedPath(path: string) {
        if (this.snapshot.selectedPath !== path) return

        this.update({ ...this.snapshot, selectedPath: null })
    }

    private readonly handleCardPathChanged = (event: Event) => {
        const { fromPath, toPath } = (event as CustomEvent<CardPathChangedEventDetail>).detail
        if (this.snapshot.selectedPath !== fromPath) return

        this.update({ ...this.snapshot, selectedPath: toPath })
    }

    private readonly handleDataServiceChanged = () => {
        this.syncProject(this.currentProjectKey())
    }

    private syncProject(projectKey: string | null) {
        if (this.projectKey === projectKey) return

        this.projectKey = projectKey
        this.update(INITIAL_SNAPSHOT)
    }

    private currentProjectKey(): string | null {
        const { project } = this.dataService.getState()
        if (!project) return null

        return `${project.id}:${project.branch}`
    }

    setViewMode(viewMode: WorkspaceViewMode) {
        this.update({ ...this.snapshot, viewMode })
    }

    private update(snapshot: WorkspaceViewSnapshot) {
        if (snapshot.selectedPath === this.snapshot.selectedPath && snapshot.viewMode === this.snapshot.viewMode) return

        this.snapshot = snapshot
        this.dispatchEvent(new CustomEvent<WorkspaceViewSnapshot>('changed', { detail: snapshot }))
    }
}

export const workspaceViewService = register('workspaceViewService', new WorkspaceViewService(dataService))

import { register } from '../service_injector'

export interface WorkspaceOpenRequest {
    path: string
}

export interface WorkspaceRevealCardRequest {
    path: string
}

export interface WorkspaceOpenCardRequest {
    cardInternalId: string
}

/**
 * Decouples the shell (search, and future callers) from the workspace view. Callers ask to open a
 * card/file by path; `ProjectWorkspace` subscribes and reveals it without changing the current view mode.
 */
export class WorkspaceNavigationService extends EventTarget {
    constructor() {
        super()
        register('workspaceNavigationService', this)
    }

    /** Requests that the workspace reveal the card or file at `path`. */
    open(path: string) {
        if (!path) throw new Error('Cannot open a workspace path without a path')

        this.dispatchEvent(new CustomEvent<WorkspaceOpenRequest>('open', { detail: { path } }))
    }

    /** Requests that the cards view select and scroll an active card into view. */
    revealCard(path: string) {
        if (!path) throw new Error('Cannot reveal a card without a path')

        this.dispatchEvent(new CustomEvent<WorkspaceRevealCardRequest>('revealCard', { detail: { path } }))
    }

    /** Requests opening current card location after resolving stable domain identity. */
    openCard(cardInternalId: string) {
        if (!cardInternalId) throw new Error('Cannot open a card without a card internal ID')

        this.dispatchEvent(new CustomEvent<WorkspaceOpenCardRequest>('openCard', { detail: { cardInternalId } }))
    }
}

export const workspaceNavigationService = new WorkspaceNavigationService()

import { useSyncExternalStore } from 'react'
import { workspaceViewService, type WorkspaceViewService } from '../../services/project/workspace_view_service'

export function useWorkspaceView(service: WorkspaceViewService = workspaceViewService) {
    return useSyncExternalStore(
        (onStoreChange) => {
            service.addEventListener('changed', onStoreChange)

            return () => service.removeEventListener('changed', onStoreChange)
        },
        () => service.getSnapshot(),
        () => service.getSnapshot(),
    )
}

