type JsonDataOwner = EventTarget & Pick<DataService, 'getState' | 'loadRepositoryTextFile'>;

function projectKey(service: JsonDataOwner) {
    const project = service.getState().project;

    return project ? `${project.id}:${project.branch}` : null;
}

function parseJson(path: string, content: string) {
    try {
        return JSON.parse(content) as JsonValue;
    } catch (error) {
        throw new Error(`Invalid JSON in ${path}`, { cause: error });
    }
}

/** Loads and owns one JSON document per active-project path. */
export class JsonDataService extends EventTarget {
    private readonly dataOwner: JsonDataOwner;
    private readonly dialogs: Pick<DialogService, 'warning'>;
    private readonly projectAccess: Pick<ProjectAccessService, 'getSnapshot'>;
    private readonly documents = new Map<string, JsonDataDocument>();
    private loadedProjectKey: string | null;

    constructor(
        dataOwner: JsonDataOwner,
        dialogs: Pick<DialogService, 'warning'>,
        projectAccess: Pick<ProjectAccessService, 'getSnapshot'> = projectAccessService,
    ) {
        super();
        this.dataOwner = dataOwner;
        this.dialogs = dialogs;
        this.projectAccess = projectAccess;
        this.loadedProjectKey = projectKey(dataOwner);
        this.dataOwner.addEventListener('changed', this.handleProjectChanged);
        this.dataOwner.addEventListener('repositoryChanged', this.handleRepositoryChanged);
    }

    async open(path: string) {
        const existing = this.documents.get(path);
        if (existing) return existing;

        const state = this.dataOwner.getState();
        if (!state.project) throw new Error('Cannot open JSON without an active project');
        if (!state.snapshot?.repositoryFiles.includes(path)) throw new Error(`JSON file does not exist in active project: ${path}`);

        const file = await this.dataOwner.loadRepositoryTextFile(path);
        const document = new JsonDataDocument(path, parseJson(path, file.content), this.projectAccess.getSnapshot());
        this.documents.set(path, document);
        this.dispatchEvent(new CustomEvent('opened', { detail: { document } }));

        return document;
    }

    find(path: string) {
        return this.documents.get(path) ?? null;
    }

    close(document: JsonDataDocument) {
        if (document.dirty || this.documents.get(document.path) !== document) return;

        this.documents.delete(document.path);
        this.dispatchEvent(new CustomEvent('closed', { detail: { document } }));
    }

    private readonly handleProjectChanged = () => {
        const nextProjectKey = projectKey(this.dataOwner);
        if (nextProjectKey === this.loadedProjectKey) return;

        this.loadedProjectKey = nextProjectKey;
        this.documents.clear();
        this.dispatchEvent(new Event('cleared'));
    };

    private readonly handleRepositoryChanged = (event: Event) => {
        const { changeKind, path } = (event as CustomEvent<ProjectWatchEvent>).detail;
        const document = this.documents.get(path);
        if (!document) return;

        if (document.dirty) {
            document.markExternalConflict();
            this.dialogs.warning(`JSON file changed outside the editor. Local draft was kept: ${path}`, { title: 'JSON file changed externally' });
            return;
        }
        if (changeKind === 'removed') {
            this.dialogs.warning(`JSON file was removed outside the editor: ${path}`, { title: 'JSON file removed' });
            return;
        }

        void this.reload(document);
    };

    private async reload(document: JsonDataDocument) {
        try {
            const file = await this.dataOwner.loadRepositoryTextFile(document.path);
            if (this.documents.get(document.path) !== document || document.dirty) return;
            document.replaceFromExternal(parseJson(document.path, file.content));
        } catch (error) {
            const message = error instanceof Error ? error.message : `JSON file could not be reloaded: ${document.path}`;
            this.dialogs.warning(message, { title: 'JSON reload failed' });
        }
    }
}

export const jsonDataService = register(
